68	    /// Performs a request to get the size and last modification time of an object.
69	    std::pair<std::optional<ObjectInfo>, Aws::S3::S3Error> tryGetObjectInfo(
70	        const S3::Client & client,
71	        const String & bucket,
72	        const String & key,
73	        const String & version_id,
74	        bool with_metadata,
75	        bool with_tags)
76	    {
77	        auto outcome = headObject(client, bucket, key, version_id);
78	        if (!outcome.IsSuccess())
79	            return {std::nullopt, outcome.GetError()};
80	
81	        const auto & result = outcome.GetResult();
82	        ObjectInfo object_info;
83	        object_info.size = static_cast<size_t>(result.GetContentLength());
84	        object_info.last_modification_time = result.GetLastModified().Seconds();
85	        object_info.etag = result.GetETag();
86	
87	        if (with_metadata)
88	            object_info.metadata = result.GetMetadata();
89	
90	        if (with_tags && result.GetTagCount() > 0)
91	            object_info.tags = getObjectTags(client, bucket, key, version_id);
92	
93	        return {object_info, {}};
94	    }
