117	ObjectAttributes getObjectTags(
118	    const S3::Client & client,
119	    const String & bucket,
120	    const String & key,
121	    const String & version_id)
122	{
123	    ObjectAttributes tags;
124	    auto tag_outcome = getObjectTagging(client, bucket, key, version_id);
125	    if (!tag_outcome.IsSuccess())
126	    {
127	        const auto & error = tag_outcome.GetError();
128	        throw S3Exception(
129	            error.GetErrorType(),
130	            "Failed to get object tags: {}. HTTP response code: {}.{}",
131	            error.GetMessage(),
132	            static_cast<size_t>(error.GetResponseCode()),
133	            getAuthenticationErrorHint(error.GetErrorType()));
134	    }
135	
136	    for (const auto & tag : tag_outcome.GetResult().GetTagSet())
137	        tags[tag.GetKey()] = tag.GetValue();
138	
139	    return tags;
140	}
